function doInstall(string $dbHost, string $dbPort, string $dbName, string $dbUser, string $dbPass, string $adminUser, string $adminPass): array {
    global $PACKED_FILES, $CONFIG_FUNCS_B64;
    $steps = [];
    $dir = __DIR__;

    if (!$dbName || !$dbUser) return ['success' => false, 'error' => 'Укажите имя БД и пользователя'];
    if (!$adminPass || mb_strlen($adminPass) < 6) return ['success' => false, 'error' => 'Пароль админа — мин. 6 символов'];

    // 1. MySQL
    try {
        $pdo = new PDO("mysql:host=$dbHost;port=$dbPort;charset=utf8mb4", $dbUser, $dbPass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
        $steps[] = "MySQL: OK";
    } catch (Exception $e) {
        return ['success' => false, 'error' => 'MySQL: ' . $e->getMessage()];
    }

    // 2. БД
    try {
        $pdo->exec("CREATE DATABASE IF NOT EXISTS `$dbName` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");
        $pdo->exec("USE `$dbName`");
        $steps[] = "БД '$dbName': OK";
    } catch (Exception $e) {
        return ['success' => false, 'error' => 'БД: ' . $e->getMessage()];
    }

    // 3. Таблицы
    $sqls = [
        "CREATE TABLE IF NOT EXISTS `licenses` (`id` int NOT NULL AUTO_INCREMENT, `license_key` varchar(64) NOT NULL, `domain` varchar(255) NOT NULL DEFAULT '', `product` varchar(100) NOT NULL DEFAULT 'kosmozaim', `plan` enum('trial','basic','pro','enterprise') NOT NULL DEFAULT 'basic', `status` enum('active','suspended','expired','revoked') NOT NULL DEFAULT 'active', `owner_name` varchar(255) DEFAULT NULL, `owner_email` varchar(255) DEFAULT NULL, `issued_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, `expires_at` timestamp NULL DEFAULT NULL, `last_check_at` timestamp NULL DEFAULT NULL, `last_check_ip` varchar(45) DEFAULT NULL, `activations_count` int NOT NULL DEFAULT 0, `max_activations` int NOT NULL DEFAULT 1, `features` text DEFAULT NULL, `notes` text DEFAULT NULL, `hardware_hash` varchar(64) DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY (`license_key`), KEY (`domain`), KEY (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS `license_log` (`id` int NOT NULL AUTO_INCREMENT, `license_id` int DEFAULT NULL, `license_key` varchar(64) DEFAULT NULL, `action` varchar(20) NOT NULL, `domain` varchar(255) DEFAULT NULL, `ip` varchar(45) DEFAULT NULL, `user_agent` varchar(500) DEFAULT NULL, `request_data` text DEFAULT NULL, `response_code` int DEFAULT NULL, `message` varchar(500) DEFAULT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY (`license_id`), KEY (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS `rate_limits` (`id` int NOT NULL AUTO_INCREMENT, `ip` varchar(45) NOT NULL, `endpoint` varchar(100) NOT NULL, `attempts` int NOT NULL DEFAULT 1, `window_start` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY (`ip`, `endpoint`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS `admins` (`id` int NOT NULL AUTO_INCREMENT, `username` varchar(100) NOT NULL, `password_hash` varchar(255) NOT NULL, `totp_secret` varchar(64) DEFAULT NULL, `totp_enabled` tinyint(1) NOT NULL DEFAULT 0, `totp_backup_codes` text DEFAULT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY (`username`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
    ];
    try {
        foreach ($sqls as $sql) $pdo->exec($sql);
        $steps[] = "Таблицы: 4 OK";
    } catch (Exception $e) {
        return ['success' => false, 'error' => 'Таблицы: ' . $e->getMessage()];
    }

    // 4. Админ
    $hash = password_hash($adminPass, PASSWORD_BCRYPT, ['cost' => 12]);
    try {
        $chk = $pdo->prepare("SELECT id FROM admins WHERE username = ?");
        $chk->execute([$adminUser]);
        if ($chk->fetch()) {
            $pdo->prepare("UPDATE admins SET password_hash = ? WHERE username = ?")->execute([$hash, $adminUser]);
            $steps[] = "Админ '$adminUser': обновлён";
        } else {
            $pdo->prepare("INSERT INTO admins (username, password_hash) VALUES (?, ?)")->execute([$adminUser, $hash]);
            $steps[] = "Админ '$adminUser': создан";
        }
    } catch (Exception $e) {
        return ['success' => false, 'error' => 'Админ: ' . $e->getMessage()];
    }

    // 5. Ключи
    $signKey = bin2hex(random_bytes(24));
    $encryptKey = bin2hex(random_bytes(24));
    $salt = bin2hex(random_bytes(16));
    $adminToken = 'lac_' . bin2hex(random_bytes(16));

    // 6. Распаковка файлов из base64
    @mkdir($dir . '/api', 0755, true);
    @mkdir($dir . '/admin', 0755, true);
    @mkdir($dir . '/data/backups', 0755, true);
    $written = 0;
    foreach ($PACKED_FILES as $name => $b64) {
        $path = $dir . '/' . $name;
        $subdir = dirname($path);
        if (!is_dir($subdir)) @mkdir($subdir, 0755, true);
        $content = base64_decode($b64);
        if (file_put_contents($path, $content) !== false) $written++;
    }
    $steps[] = "Файлы: $written распаковано";

    // 7. config.php
    $dbPassEsc = addcslashes($dbPass, "'\\");
    $funcsCode = base64_decode($CONFIG_FUNCS_B64);

    $config = "<?php\n"
        . "// KZM License Server — config (generated " . date('Y-m-d H:i:s') . ")\n\n"
        . "mb_internal_encoding('UTF-8');\n"
        . "ini_set('default_charset', 'UTF-8');\n\n"
        . "function getDB(): PDO {\n"
        . "    static \$pdo = null;\n"
        . "    if (\$pdo) return \$pdo;\n"
        . "    \$pdo = new PDO(\"mysql:host=$dbHost;port=$dbPort;dbname=$dbName;charset=utf8mb4\", '$dbUser', '$dbPassEsc', [\n"
        . "        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n"
        . "        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\n"
        . "    ]);\n"
        . "    \$pdo->exec(\"SET NAMES utf8mb4\");\n"
        . "    return \$pdo;\n"
        . "}\n\n"
        . "define('LICENSE_SIGN_KEY', '$signKey');\n"
        . "define('LICENSE_ENCRYPT_KEY', '$encryptKey');\n"
        . "define('LICENSE_SALT', '$salt');\n"
        . "define('ADMIN_API_TOKEN', '$adminToken');\n\n"
        . $funcsCode;

    if (file_put_contents($dir . '/config.php', $config) === false) {
        return ['success' => false, 'error' => 'Не удалось записать config.php'];
    }
    $steps[] = "config.php: OK";

    // 8. Проверка
    try {
        require_once $dir . '/config.php';
        getDB()->query("SELECT 1");
        $steps[] = "Проверка БД: OK";
    } catch (Exception $e) {
        $steps[] = "⚠️ Проверка: " . $e->getMessage();
    }

    return ['success' => true, 'steps' => $steps];
}
